/**
 * A plan change ends the trial: the org has made a deliberate choice. The
 * workspace's own `plan` column is written in the same transaction, so the
 * two records cannot disagree after a change.
 */
export async function updateSubscriptionPlan(
  orgId: OrgId,
  plan: PlanId,
  interval: BillingInterval,
): Promise<Subscription> {
  const stamp = toIsoTimestamp(new Date());

  return getDb().transaction((tx) => {
    const row = tx
      .update(subscriptions)
      .set({ plan, interval, status: "active", updatedAt: stamp })
      .where(orgPredicate(subscriptions.orgId, orgId))
      .returning()
      .get();

    if (!row) throw new Error(`Subscription for org ${orgId} not found`);

    tx.update(organizations)
      .set({ plan, updatedAt: stamp })
      .where(orgPredicate(organizations.id, orgId))
      .run();

    return toSubscription(row);
  });
}

