import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("./server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("./server/_support/doubles/misc")).loggerModule);

import { eq } from "drizzle-orm";
import { getDb, organizations } from "@/server/db";
import { isEnabled } from "@/lib/feature-flags";
import { consumeRateLimit, resetRateLimits } from "@/lib/rate-limit";
import { runTrialExpiryJob } from "@/server/jobs/trial-expiry-job";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as billingService from "@/server/services/billing-service";
import * as projectService from "@/server/services/project-service";
import * as webhookService from "@/server/services/webhook-service";
import { subscribe } from "@/lib/event-bus";
import { createTenant, useTemporaryDatabase } from "./server/_support/fixtures";
import type { CreateProjectInput } from "@/schemas/project";
import type { OrgId } from "@/types/common";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

function projectInput(orgId: OrgId, n: number): CreateProjectInput {
  return {
    orgId,
    name: `Project ${n}`,
    slug: `project-${n}`,
    key: `PR${n}`,
    description: null,
    visibility: "org",
    leadId: null,
    color: "#6366f1",
    targetDate: null,
  };
}

const IN_30_DAYS = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000);

describe("plan follows the subscription", () => {
  it("upgrade on billing applies to projects, plan shown, and org reads", async () => {
    const tenant = await createTenant("up-free", "free");
    await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "growth",
      interval: "monthly",
    });

    const org = await orgRepo.findOrgById(tenant.org.id);
    expect(org?.plan).toBe("growth");
    expect(isEnabled("csv_export", { orgId: tenant.org.id, userId: null, plan: org!.plan, role: null })).toBe(true);

    await projectService.createProject(tenant.actors.member, projectInput(tenant.org.id, 2));
    await projectService.createProject(tenant.actors.member, projectInput(tenant.org.id, 3));
    await projectService.createProject(tenant.actors.member, projectInput(tenant.org.id, 4));
  });

  it("disagreeing legacy column is overridden by the subscription", async () => {
    const tenant = await createTenant("legacy", "growth");
    getDb().update(organizations).set({ plan: "free" }).where(eq(organizations.id, tenant.org.id)).run();

    expect((await orgRepo.findOrgById(tenant.org.id))?.plan).toBe("growth");
    await projectService.createProject(tenant.actors.member, projectInput(tenant.org.id, 2));
    await projectService.createProject(tenant.actors.member, projectInput(tenant.org.id, 3));
  });

  it("org without a subscription keeps the plan stored on the workspace", async () => {
    const owner = await createTenant("nosub", "free");
    getDb().delete(await import("@/server/db").then((m) => m.subscriptions)).run();
    const org = await orgRepo.findOrgById(owner.org.id);
    expect(org?.plan).toBe("free");
  });

